L["Date and Time formatting guide Desc"] = [=[{a} - 周（英文缩写）（例如Wed）
{A} - 周（英文全称）（例如Wednesday）
{b} - 月（英文缩写）（例如Sep）
{B} - 月（英文全称）（例如September）
{c} - 日期和时间（本地习惯）（例如23/04/07 10:20:41）
{C} - 世纪（年份/100）（例如20）
{d} - 日/月（01 - 31）
{D} - 等同于%m/%d/%y（例如04/23/07）
{e} - 日/月（1 - 31）
{H} - 24小时制（00 - 23）
{I} - 12小时制（01 - 12）
{j} - 日/年（001 - 366）
{k} - 24小时制（0 - 23）
{l} - 12小时制（1 - 12）
{m} - 月（01 - 12）
{M} - 分钟（00 - 59）
{p} - AM/PM（本地习惯）（例如AM/PM）
{P} - AM/PM（本地习惯）（例如am/pm）
{R} - 等同于%H:%M（10:00）
{s} - Unix时间戳，从1970-01-01 00:00:00 UTC开始经过的秒数（1177323641）
{S} - 秒（00 - 59）
{u} - 周（1 - 7；1为周一）
{U} - 周/年，周日为每周第一天（00 - 53）
{w} - 周（数字）（0 - 6；0为周日）
{W} - 周/年，周一为每周第一天（00 - 53）
{x} - 日期（本地习惯）（标准日期）
{X} - 时间（本地习惯）（标准时间）
{y} - 无世纪年（00 - 99）（例如07）
{Y} - 完整年份（例如2007）
{z} - GMT时区（例如+0200）
{Z} - 时区名称或缩写（未知时区不显示）]=]
